import{_ as p,a0 as a,w as i,s as d,ao as r,I as e,x as o,a1 as u,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何正確雙啓動Ubuntu和Windows雙系統 | LCTT x X-CMD","titleTemplate":false,"description":"如何正確雙啓動Ubuntu和Windows雙系統 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何正確雙啓動Ubuntu和Windows雙系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何正確雙啓動Ubuntu和Windows雙系統 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/How to Dual Boot Ubuntu and Windows Properly","title":"如何正確雙啓動Ubuntu和Windows雙系統","tag":"201401","desc":""},"relativePath":"201401/How to Dual Boot Ubuntu and Windows Properly.md","filePath":"[post].md"}'),l={name:"201401/How to Dual Boot Ubuntu and Windows Properly.md"};function w(b,t,m,U,W,T){const n=a("Link");return i(),d("div",null,[t[11]||(t[11]=r(`<h1 id="如何正確雙啓動ubuntu和windows雙系統" tabindex="-1">如何正確雙啓動Ubuntu和Windows雙系統 <a class="header-anchor" href="#如何正確雙啓動ubuntu和windows雙系統" aria-label="Permalink to “如何正確雙啓動Ubuntu和Windows雙系統”">​</a></h1><p><strong>儘管微軟想讓你信任Windows，但一個Linux操作系統和一個Windows操作系統可以在同一台PC上和平共存。這個文章會指導你如何讓一個Ubuntu系統和Windows操作系統並行運行。</strong></p><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Dual-Boot-Ubuntu-and-Windows-Properly-415377-2.jpg" alt=""></p><p>你必須考慮兩種場景，同時你也必須決定哪一種適合你。這裏必須要考慮安裝順序。在你已經安裝好Ubuntu操作系統後再安裝Windows會有一點問題，因為微軟似乎不太在意其他小夥伴。</p><p>如果你是在已經安裝好Windows後安裝Ubuntu，那麼事情會變得簡單多了，幾乎沒有任何工作和準備是必需的。</p><p>讓我們開始處理更加困難的問題。如果你已經有一個Ubuntu系統，想安裝Windows，你會丟掉GRUB，它是默認的引導程序。Windows不會在意它，並會擦除它。</p><p>如果你已經犯了這個錯誤，但你並沒有重寫Linux分區，請別沮喪。數據仍然在那裏，你需要的是一個含有Ubuntu（最新到13.10版本）的可啓動live CD。你需要安裝一個名為Boot-Repair的應用程序，使用PPA來安裝它。</p><p>記住，如果你使用U盤，安裝應用會相當簡單，因為Ubuntu安裝鏡像是混合鏡像。用Live CD啓動一個Ubuntu會話，打開終端，然後輸入下列指令：</p><pre><code>sudo add-apt-repository ppa:yannubuntu/boot-repair &amp;&amp; sudo apt-get update
sudo apt-get install -y boot-repair &amp;&amp; (boot-repair &amp;)
</code></pre><p>打開應用程序，點擊推薦修復，然後等待。在這個步驟完成後，重啓機器，你就會重新看到GRUB，實現雙啓動。</p><p>在另一方面，如果你已經安裝好Windows，想要安裝Ubuntu，事情會更加簡單。啓動Ubuntu安裝，選擇安裝到一個非Windows分區，格式化為EXT4，選擇引導程序的位置，然後就搞定了。</p><p>如果你選擇將引導程序安裝在和Windows安裝的同一塊硬盤上，它會擦除微軟的引導程序。這樣沒有問題，因為GRUB會識別出WIndows操作系統，你不會丟掉它。如果你把它安裝在其它地方，譬如在另一塊硬盤上，當你選擇從不同的硬盤啓動時，你會看到它們兩個。</p><p>開始享受你的Ubuntu和Windows雙系統啓動的樂趣吧！</p><hr>`,14)),e("p",null,[t[1]||(t[1]=o("via: ",-1)),u(n,{href:"http://news.softpedia.com/news/How-to-Dual-Boot-Ubuntu-and-Windows-Properly-415377.shtml"},{default:s(()=>[...t[0]||(t[0]=[o("http://news.softpedia.com/news/How-to-Dual-Boot-Ubuntu-and-Windows-Properly-415377.shtml",-1)])]),_:1})]),e("p",null,[t[4]||(t[4]=o("譯者：",-1)),u(n,{href:"https://github.com/KayGuoWhu"},{default:s(()=>[...t[2]||(t[2]=[o("KayGuoWhu",-1)])]),_:1}),t[5]||(t[5]=o(" 校對：",-1)),u(n,{href:"https://github.com/wxy"},{default:s(()=>[...t[3]||(t[3]=[o("wxy",-1)])]),_:1})]),e("p",null,[t[8]||(t[8]=o("本文由 ",-1)),u(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[6]||(t[6]=[o("LCTT",-1)])]),_:1}),t[9]||(t[9]=o(" 原創翻譯，",-1)),u(n,{href:"http://linux.cn/"},{default:s(()=>[...t[7]||(t[7]=[o("Linux中國",-1)])]),_:1}),t[10]||(t[10]=o(" 榮譽推出",-1))])])}const P=p(l,[["render",w]]);export{x as __pageData,P as default};
